(() => {
  const upper = highest(h, params.channel);
  const lower = lowest(l, params.channel);
  const a = atr(params.atrPeriod);
  const sd = stdev(c, params.channel);
  if (na(upper[i - 1]) || na(lower[i - 1]) || na(a[i])) return { side: 'flat', strength: 0, reason: 'warmup' };

  const volOk = a[i] >= params.atrMinMult * sd[i];
  if (c[i] > upper[i - 1] && volOk) {
    return {
      side: 'long',
      strength: clamp((c[i] - upper[i - 1]) / a[i], 0.1, 1),
      reason: 'breakout above ' + params.channel + ' bar high',
      stopLoss: c[i] - a[i] * params.atrStopMult,
      takeProfit: c[i] + a[i] * params.atrTargetMult
    };
  }
  if (c[i] < lower[i - 1] && volOk) {
    return {
      side: 'short',
      strength: clamp((lower[i - 1] - c[i]) / a[i], 0.1, 1),
      reason: 'breakdown below ' + params.channel + ' bar low',
      stopLoss: c[i] + a[i] * params.atrStopMult,
      takeProfit: c[i] - a[i] * params.atrTargetMult
    };
  }
  return { side: 'flat', strength: 0, reason: 'no-breakout' };
})()
